// Alemán B1+: mismo formato que advanced_english_b1plus.js.
export const GERMAN_B1_PLUS=[
{id:'de-01',level:'B1+',title:'Lo que ya había pasado',goal:'contar qué ocurrió antes de otro hecho del pasado.',
rule:'El Plusquamperfekt se forma con hatte o war + participio al final: Ich hatte gegessen, Sie war gegangen. Marca lo anterior a otro pasado. Suele ir con nachdem, que manda el verbo al final: Nachdem ich gegessen hatte, ging ich. Tras nachdem nunca va el mismo tiempo que en la frase principal: Plusquamperfekt con Präteritum.',
items:[['Nachdem ich gegessen hatte, ging ich los.','Después de haber comido, me fui.'],['Der Zug war schon abgefahren.','El tren ya se había ido.'],['Sie hatte das nicht gewusst.','Ella no lo había sabido.'],['Bevor er kam, hatte ich aufgeräumt.','Antes de que viniera, yo había ordenado.'],['abfahren','partir'],['der Bahnsteig','el andén'],['verpassen','perder (un tren)'],['rechtzeitig','a tiempo']],
textTitle:'Der verpasste Zug',text:[['Als ich am Bahnhof ankam, war der Zug schon abgefahren.','Cuando llegué a la estación, el tren ya se había ido.'],['Ich hatte am Morgen zu lange geschlafen.','Por la mañana había dormido demasiado.'],['Nachdem ich mit der Firma telefoniert hatte, nahm ich den nächsten Zug.','Después de telefonear a la empresa, tomé el siguiente tren.'],['Mein Chef hatte zum Glück nichts gemerkt.','Por suerte, mi jefe no había notado nada.'],['Seitdem stelle ich immer zwei Wecker.','Desde entonces siempre pongo dos despertadores.']],
questions:[['¿Por qué perdió el tren?','Durmió demasiado','Hubo una huelga','Se equivocó de andén'],['¿Qué hace ahora?','Pone dos despertadores','Va en coche','Cambió de empresa']],
drills:[['Completa: Nachdem er ___ (arbeiten, Plusquamperfekt), ging er nach Hause.','gearbeitet hatte','Nachdem er gearbeitet hatte, ging er nach Hause.'],['Escribe en alemán: «Ya había salido.» (ich, gehen)','Ich war schon gegangen.'],['Completa con hatte o war: Sie ___ schon angekommen.','war']],
write:{prompt:'Cuenta un día en que algo salió mal porque antes había pasado otra cosa.',model:'Letzte Woche kam ich zu spät zur Arbeit. Ich hatte mein Handy zu Hause vergessen. Nachdem ich zurückgegangen war, verpasste ich den Bus.'}},
{id:'de-02',level:'B1+',title:'Antes, después y mientras',goal:'ordenar hechos con conectores de tiempo.',
rule:'Bevor, nachdem, während, seitdem y bis abren oraciones secundarias: coma y verbo al final. Si la secundaria va primero, la principal empieza por el verbo: Bevor ich gehe, rufe ich dich an. Wenn sirve para algo repetido y para el futuro; als, para un hecho único del pasado: Als ich klein war.',
items:[['Bevor ich gehe, rufe ich dich an.','Antes de irme, te llamo.'],['Während er kochte, las sie.','Mientras él cocinaba, ella leía.'],['Seitdem wir hier wohnen, bin ich glücklich.','Desde que vivimos aquí, soy feliz.'],['Warte, bis ich komme.','Espera hasta que yo llegue.'],['Immer wenn es regnet, bleibe ich zu Hause.','Siempre que llueve, me quedo en casa.'],['umziehen','mudarse'],['die Wohnung','el piso'],['sich gewöhnen an','acostumbrarse a']],
textTitle:'Der Umzug',text:[['Bevor wir nach Hamburg gezogen sind, haben wir in einem Dorf gewohnt.','Antes de mudarnos a Hamburgo, vivíamos en un pueblo.'],['Seitdem wir hier wohnen, fahre ich jeden Tag mit der U-Bahn.','Desde que vivimos aquí, voy cada día en metro.'],['Während ich arbeite, lernt meine Frau Deutsch.','Mientras trabajo, mi esposa aprende alemán.'],['Es hat lange gedauert, bis wir uns an die Stadt gewöhnt haben.','Tardamos mucho en acostumbrarnos a la ciudad.'],['Immer wenn die Sonne scheint, gehen wir an die Elbe.','Siempre que hace sol, vamos al Elba.']],
questions:[['¿Dónde vivían antes?','En un pueblo','En Berlín','En Hamburgo'],['¿Qué hace su esposa mientras él trabaja?','Aprende alemán','Trabaja también','Va al Elba']],
drills:[['Une con bevor: Ich frühstücke. Ich gehe.','Bevor ich gehe, frühstücke ich.','Ich frühstücke, bevor ich gehe.'],['Elige als o wenn: ___ ich jung war, wohnte ich in Köln.','Als'],['Une con seitdem: Ich lerne Deutsch. Ich verstehe mehr.','Seitdem ich Deutsch lerne, verstehe ich mehr.']],
write:{prompt:'Describe un cambio en tu vida usando bevor, seitdem y während.',model:'Bevor ich hier gearbeitet habe, war ich Student. Seitdem ich arbeite, habe ich wenig Zeit. Während ich fahre, höre ich Deutsch.'}},
{id:'de-03',level:'B1+',title:'Preguntar sin preguntar',goal:'hacer preguntas indirectas y corteses.',
rule:'Las preguntas indirectas son secundarias: verbo al final. Con palabra interrogativa se mantiene: Wissen Sie, wo der Bahnhof ist? Sin ella se usa ob: Ich weiß nicht, ob er kommt. Ob es «si» de duda; wenn es «si» de condición. Decir «Ich weiß nicht, wenn er kommt» es un error típico.',
items:[['Wissen Sie, wo der Bahnhof ist?','¿Sabe dónde está la estación?'],['Ich weiß nicht, ob er kommt.','No sé si viene.'],['Können Sie mir sagen, wann das Büro öffnet?','¿Puede decirme cuándo abre la oficina?'],['Ich frage mich, warum sie nicht antwortet.','Me pregunto por qué no responde.'],['die Auskunft','la información'],['das Formular','el formulario'],['ausfüllen','rellenar'],['die Unterlagen','los documentos']],
textTitle:'Auf dem Amt',text:[['Ich wollte wissen, welche Unterlagen ich brauche.','Quería saber qué documentos necesito.'],['Die Dame fragte mich, ob ich einen Termin hatte.','La señora me preguntó si tenía cita.'],['Ich wusste nicht, wo ich das Formular bekommen konnte.','No sabía dónde podía conseguir el formulario.'],['Sie erklärte mir, wie ich es online ausfüllen kann.','Me explicó cómo rellenarlo en línea.'],['Jetzt warte ich und frage mich, wann die Antwort kommt.','Ahora espero y me pregunto cuándo llegará la respuesta.']],
questions:[['¿Qué le preguntó la señora?','Si tenía cita','Dónde vivía','Cuánto ganaba'],['¿Cómo se rellena el formulario?','En línea','A mano','Por teléfono']],
drills:[['Hazla indirecta: Wo wohnt er? → Ich weiß nicht, ___','Ich weiß nicht, wo er wohnt.','wo er wohnt'],['Hazla indirecta: Kommt sie? → Ich frage, ___','Ich frage, ob sie kommt.','ob sie kommt'],['Elige ob o wenn: Ich weiß nicht, ___ das stimmt.','ob']],
write:{prompt:'Escribe tres preguntas corteses para pedir información en una oficina.',model:'Könnten Sie mir sagen, wann das Büro geöffnet ist? Wissen Sie, welche Unterlagen ich brauche? Ich möchte wissen, ob ich online bezahlen kann.'}},
{id:'de-04',level:'B1+',title:'Lo que se ha hecho',goal:'usar la pasiva en pasado y con modales.',
rule:'La pasiva en Perfekt usa sein + participio + worden, sin ge-: Das Haus ist verkauft worden. En Präteritum: wurde verkauft. Con modal: Das muss gemacht werden; en pasado: Das musste gemacht werden. Si interesa el resultado se usa sein + participio: Die Tür ist geschlossen, ya está cerrada. Agente con von.',
items:[['Das Haus ist verkauft worden.','La casa ha sido vendida.'],['Der Brief wurde gestern geschickt.','La carta se envió ayer.'],['Das muss heute gemacht werden.','Esto debe hacerse hoy.'],['Die Tür ist geschlossen.','La puerta está cerrada.'],['Die Brücke wurde von Studenten gebaut.','El puente fue construido por estudiantes.'],['bauen','construir'],['reparieren','reparar'],['eröffnen','inaugurar']],
textTitle:'Eine alte Brücke',text:[['Die Brücke wurde 1890 gebaut.','El puente se construyó en 1890.'],['Im Krieg ist sie fast völlig zerstört worden.','En la guerra fue destruido casi por completo.'],['Danach musste sie neu geplant werden.','Después tuvo que planificarse de nuevo.'],['Letztes Jahr wurde sie repariert und wieder eröffnet.','El año pasado se reparó y se reabrió.'],['Heute wird sie täglich von Tausenden benutzt.','Hoy la usan miles de personas cada día.']],
questions:[['¿Cuándo se construyó?','En 1890','En la guerra','El año pasado'],['¿Qué pasó el año pasado?','Se reabrió','Se destruyó','Se vendió']],
drills:[['Pasa a pasiva Perfekt: Man hat das Auto repariert.','Das Auto ist repariert worden.'],['Pasa a pasiva: Man muss den Text lesen.','Der Text muss gelesen werden.'],['Pasa a pasiva Präteritum: Man baute das Haus 1900.','Das Haus wurde 1900 gebaut.']],
write:{prompt:'Explica la historia de un edificio o lugar conocido con pasiva.',model:'Die Kirche wurde vor 300 Jahren gebaut. Sie ist zweimal zerstört worden. Heute wird sie von vielen Touristen besucht.'}},
{id:'de-05',level:'B1+',title:'Lo que habría pasado',goal:'hablar de lo que pudo ser y no fue.',
rule:'El Konjunktiv II del pasado es hätte o wäre + participio: Ich hätte das gemacht, Ich wäre gekommen. Con modal van dos infinitivos al final: Ich hätte kommen können, Du hättest fragen sollen. Con wenn, el verbo se va al final: Wenn ich das gewusst hätte, wäre ich gekommen. Sin wenn, empieza por el verbo: Hätte ich das gewusst…',
items:[['Wenn ich das gewusst hätte, wäre ich gekommen.','Si lo hubiera sabido, habría venido.'],['Du hättest fragen sollen.','Deberías haber preguntado.'],['Ich hätte dir helfen können.','Habría podido ayudarte.'],['Das wäre nicht passiert.','Eso no habría pasado.'],['bereuen','arrepentirse'],['die Chance','la oportunidad'],['ablehnen','rechazar'],['eigentlich','en realidad']],
textTitle:'Die verpasste Chance',text:[['Vor fünf Jahren bekam ich ein Angebot aus Wien.','Hace cinco años recibí una oferta de Viena.'],['Ich habe es abgelehnt, weil ich Angst hatte.','La rechacé porque tenía miedo.'],['Wenn ich zugesagt hätte, hätte ich viel gelernt.','Si hubiera aceptado, habría aprendido mucho.'],['Aber dann hätte ich meine Frau nicht kennengelernt.','Pero entonces no habría conocido a mi esposa.'],['Eigentlich bereue ich gar nichts.','En realidad no me arrepiento de nada.']],
questions:[['¿Qué hizo con la oferta?','La rechazó','La aceptó','La olvidó'],['¿Se arrepiente?','No','Sí, mucho','No lo sabe']],
drills:[['Completa: Wenn ich Zeit gehabt ___, wäre ich gekommen.','hätte'],['Escribe en alemán: «Deberías haber llamado.»','Du hättest anrufen sollen.'],['Completa con hätte o wäre: Ich ___ früher gegangen.','wäre']],
write:{prompt:'¿Qué habría pasado si hubieras tomado otra decisión importante?',model:'Wenn ich nicht Deutsch gelernt hätte, wäre ich nie nach Berlin gefahren. Ich hätte auch meine Freunde nicht kennengelernt.'}},
{id:'de-06',level:'B1+',title:'Contar lo que otros dicen',goal:'citar a alguien con el Konjunktiv I.',
rule:'En noticias y textos formales se cita con Konjunktiv I: raíz + -e. Lo esencial es er sei, er habe, er komme: Er sagt, er sei krank. Para el pasado: er habe gesagt, er sei gefahren. Al hablar se prefiere indicativo o Konjunktiv II: Er sagt, er ist krank. Dass también vale: Er sagt, dass er krank ist.',
items:[['Er sagt, er sei krank.','Dice que está enfermo.'],['Sie sagte, sie habe keine Zeit.','Dijo que no tenía tiempo.'],['Der Minister erklärte, er werde kommen.','El ministro declaró que vendría.'],['Laut Polizei sei niemand verletzt.','Según la policía nadie está herido.'],['die Nachricht','la noticia'],['laut','según'],['behaupten','afirmar'],['der Sprecher','el portavoz']],
textTitle:'Die Nachrichten',text:[['Ein Sprecher der Stadt sagte, der Bau sei fast fertig.','Un portavoz de la ciudad dijo que la obra está casi terminada.'],['Die Kosten seien aber höher als geplant.','Pero los costes serían más altos de lo previsto.'],['Laut Bürgermeister werde die Linie im Mai eröffnet.','Según el alcalde, la línea se abrirá en mayo.'],['Kritiker behaupten, man habe zu spät reagiert.','Los críticos afirman que se reaccionó demasiado tarde.'],['Eine Bürgerin sagte, sie habe genug von den Baustellen.','Una ciudadana dijo que está harta de las obras.']],
questions:[['¿Cuándo se abre la línea?','En mayo','Ya está abierta','No se sabe'],['¿Qué dicen los críticos?','Se reaccionó tarde','Es barata','Terminó pronto']],
drills:[['Pasa a Konjunktiv I: Er sagt: «Ich bin müde.»','Er sagt, er sei müde.'],['Pasa a Konjunktiv I: Sie sagt: «Ich habe Hunger.»','Sie sagt, sie habe Hunger.'],['Escribe en alemán: «Según el médico, todo está bien.»','Laut Arzt ist alles gut.','Laut dem Arzt ist alles gut.','Laut Arzt sei alles gut.','Laut dem Arzt sei alles gut.']],
write:{prompt:'Resume una noticia reciente citando a alguien.',model:'Die Regierung sagte, die Preise würden sinken. Ein Experte erklärte, das sei zu optimistisch. Laut einer Umfrage sind viele Bürger besorgt.'}},
{id:'de-07',level:'B1+',title:'Sin hacer, en vez de hacer',goal:'usar ohne zu, statt zu y otros infinitivos.',
rule:'Ohne … zu significa sin hacer: Er ging, ohne zu grüßen. Statt … zu, en lugar de: Statt zu lernen, schläft er. Solo valen si el sujeto es el mismo; si cambia, ohne dass. Brauchen + nicht + zu significa no hacer falta: Du brauchst nicht zu kommen. Lassen sin zu: Ich lasse mein Auto reparieren, hago que me lo reparen.',
items:[['Er ging, ohne zu grüßen.','Se fue sin saludar.'],['Statt zu lernen, schläft er.','En lugar de estudiar, duerme.'],['Du brauchst nicht zu kommen.','No hace falta que vengas.'],['Ich lasse mein Auto reparieren.','Mando a reparar mi coche.'],['Sie scheint müde zu sein.','Parece estar cansada.'],['höflich','cortés'],['sich verabschieden','despedirse'],['stattdessen','en cambio']],
textTitle:'Der neue Kollege',text:[['Unser neuer Kollege kam, ohne sich vorzustellen.','Nuestro compañero nuevo llegó sin presentarse.'],['Statt mit uns zu essen, bleibt er am Schreibtisch.','En vez de comer con nosotros, se queda en su escritorio.'],['Er scheint schüchtern zu sein.','Parece ser tímido.'],['Gestern ließ er seine Tasche im Büro liegen.','Ayer dejó su bolso en la oficina.'],['Ich brachte sie ihm, und seitdem redet er mit uns.','Se lo llevé, y desde entonces habla con nosotros.']],
questions:[['¿Cómo parece el compañero?','Tímido','Enfadado','Enfermo'],['¿Qué olvidó?','Su bolso','Su comida','Su móvil']],
drills:[['Une: Er geht. Er sagt nichts. (ohne)','Er geht, ohne etwas zu sagen.'],['Une: Sie arbeitet nicht. Sie spielt. (statt)','Statt zu arbeiten, spielt sie.'],['Escribe en alemán: «Mando a cortar mi pelo.»','Ich lasse mir die Haare schneiden.']],
write:{prompt:'Describe qué haces tú mismo y qué mandas a hacer, con lassen.',model:'Ich koche selbst, aber ich lasse mein Auto reparieren. Statt zu putzen, gehe ich oft spazieren. Ich brauche nicht früh aufzustehen.'}},
{id:'de-08',level:'B1+',title:'Participios como adjetivos',goal:'entender frases largas típicas del alemán escrito.',
rule:'Un participio puede funcionar como adjetivo y toma sus terminaciones. Partizip I (infinitivo + d): das schlafende Kind, el niño que duerme. Partizip II: das gekochte Ei, el huevo cocido. En textos escritos se alargan antes del nombre: die im Mai eröffnete Linie, la línea abierta en mayo. Busca primero el artículo y luego el nombre.',
items:[['das schlafende Kind','el niño dormido'],['das gekochte Ei','el huevo cocido'],['die steigenden Preise','los precios en aumento'],['der gestern geschriebene Brief','la carta escrita ayer'],['die Mehrheit','la mayoría'],['wachsend','creciente'],['bekannt','conocido'],['die Umfrage','la encuesta']],
textTitle:'Die Studie',text:[['Die im Juni veröffentlichte Studie zeigt ein klares Bild.','El estudio publicado en junio muestra un panorama claro.'],['Die steigenden Mieten sind ein wachsendes Problem.','Los alquileres en aumento son un problema creciente.'],['Viele der befragten Personen wollen die Stadt verlassen.','Muchas de las personas encuestadas quieren dejar la ciudad.'],['Die betroffenen Familien brauchen mehr Hilfe.','Las familias afectadas necesitan más ayuda.'],['Die von der Stadt geplanten Wohnungen reichen nicht.','Las viviendas planeadas por la ciudad no bastan.']],
questions:[['¿Qué problema crece?','Los alquileres','El paro','El tráfico'],['¿Bastan las viviendas planeadas?','No','Sí','Aún no se sabe']],
drills:[['Reduce: das Kind, das lacht →','das lachende Kind'],['Reduce: der Kuchen, der gebacken wurde →','der gebackene Kuchen'],['Traduce: die wachsende Stadt','la ciudad creciente','la ciudad que crece']],
write:{prompt:'Describe tu barrio usando al menos tres participios como adjetivos.',model:'In meinem Viertel gibt es viele renovierte Häuser. Die wachsende Zahl der Touristen stört die dort lebenden Menschen.'}},
{id:'de-09',level:'B1+',title:'Expresiones fijas de nombre y verbo',goal:'sonar natural con combinaciones de nombre y verbo.',
rule:'El alemán formal une un nombre y un verbo casi vacío: eine Entscheidung treffen (decidir), eine Frage stellen (preguntar), Hilfe leisten (ayudar), in Frage kommen (entrar en consideración), zur Verfügung stehen (estar disponible), Bescheid sagen (avisar). Se aprenden enteras. Traducir del español da errores: se dice eine Entscheidung treffen, no «machen».',
items:[['Wir müssen eine Entscheidung treffen.','Debemos tomar una decisión.'],['Darf ich eine Frage stellen?','¿Puedo hacer una pregunta?'],['Sag mir bitte Bescheid.','Avísame, por favor.'],['Das kommt nicht in Frage.','Eso ni pensarlo.'],['Ich stehe zur Verfügung.','Estoy a disposición.'],['Rücksicht nehmen','tener consideración'],['in Kontakt bleiben','seguir en contacto'],['Erfahrung sammeln','adquirir experiencia']],
textTitle:'Ein Teamgespräch',text:[['Heute müssen wir eine wichtige Entscheidung treffen.','Hoy debemos tomar una decisión importante.'],['Mehr Überstunden kommen nicht in Frage.','Más horas extra ni pensarlo.'],['Wir sollten auf die Familien Rücksicht nehmen.','Deberíamos tener consideración con las familias.'],['Julia stellt noch eine Frage zum Budget.','Julia hace otra pregunta sobre el presupuesto.'],['Ich sage euch morgen Bescheid.','Mañana les aviso.']],
questions:[['¿Qué queda descartado?','Más horas extra','El presupuesto','La reunión'],['¿Quién pregunta por el presupuesto?','Julia','El jefe','Nadie']],
drills:[['Completa: eine Entscheidung ___','treffen'],['Completa: eine Frage ___','stellen'],['Escribe en alemán: «Avísame mañana.»','Sag mir morgen Bescheid.']],
write:{prompt:'Cuenta una decisión de grupo usando tres de estas expresiones.',model:'Wir mussten eine Entscheidung treffen. Ein neues Auto kam nicht in Frage. Mein Bruder stellte viele Fragen und sagte uns dann Bescheid.'}},
{id:'de-10',level:'B1+',title:'Formar palabras',goal:'deducir palabras nuevas por su forma.',
rule:'Con pocas reglas multiplicas el vocabulario. -ung convierte verbos en nombres femeninos: entscheiden → die Entscheidung. -heit y -keit, adjetivos en nombres: frei → die Freiheit. -bar significa que se puede: lesbar. -los, sin: arbeitslos. un- niega: unmöglich. Los compuestos toman el género de la última palabra: das Haus + die Tür → die Haustür.',
items:[['die Entscheidung','la decisión'],['die Freiheit','la libertad'],['die Möglichkeit','la posibilidad'],['arbeitslos','desempleado'],['unmöglich','imposible'],['essbar','comestible'],['die Haustür','la puerta de casa'],['die Gesundheit','la salud']],
textTitle:'Arbeit und Freiheit',text:[['Die Arbeitslosigkeit ist eine große Unsicherheit für viele Familien.','El desempleo es una gran inseguridad para muchas familias.'],['Eine gute Ausbildung gibt jungen Menschen mehr Möglichkeiten.','Una buena formación da más posibilidades a los jóvenes.'],['Trotzdem ist nicht alles planbar.','Aun así, no todo es planificable.'],['Viele suchen heute mehr Freiheit und Gesundheit statt Geld.','Hoy muchos buscan más libertad y salud en lugar de dinero.'],['Diese Veränderung ist für Firmen eine Herausforderung.','Este cambio es un desafío para las empresas.']],
questions:[['¿Qué buscan muchos hoy?','Libertad y salud','Solo dinero','Más horas'],['¿Qué da la formación?','Más posibilidades','Más riesgos','Más impuestos']],
drills:[['Forma el nombre: wohnen →','die Wohnung'],['Forma el nombre: schön →','die Schönheit'],['¿Qué género tiene der Bahnhof + die Uhr?','die Bahnhofsuhr','die']],
write:{prompt:'Escribe cinco frases usando nombres en -ung y -heit o -keit.',model:'Die Entscheidung war schwer. Meine Gesundheit ist wichtig. Die Wohnung bietet viele Möglichkeiten und viel Freiheit.'}},
{id:'de-11',level:'B1+',title:'Escribir un correo formal',goal:'redactar un correo formal en alemán.',
rule:'Saludo: Sehr geehrte Frau Weber, / Sehr geehrter Herr Klein, / Sehr geehrte Damen und Herren. Tras la coma, la primera palabra va en minúscula. Motivo: ich schreibe Ihnen, weil… Petición: Könnten Sie mir bitte…? Cierre: Ich freue mich auf Ihre Antwort. Mit freundlichen Grüßen. Sie, Ihnen, Ihr siempre con mayúscula.',
items:[['Sehr geehrte Damen und Herren,','Estimados señores:'],['ich schreibe Ihnen wegen Ihrer Anzeige.','les escribo por su anuncio.'],['Könnten Sie mir bitte Informationen schicken?','¿Podrían enviarme información?'],['Ich freue mich auf Ihre Antwort.','Quedo a la espera de su respuesta.'],['Mit freundlichen Grüßen','Atentamente'],['die Bewerbung','la solicitud de empleo'],['der Lebenslauf','el currículum'],['im Anhang','adjunto']],
textTitle:'Eine Bewerbung',text:[['Sehr geehrte Frau Weber,','Estimada señora Weber:'],['ich bewerbe mich um die Stelle als Assistentin.','solicito el puesto de asistente.'],['Ich habe fünf Jahre Erfahrung im Kundenservice.','Tengo cinco años de experiencia en atención al cliente.'],['Im Anhang finden Sie meinen Lebenslauf.','Adjunto encontrará mi currículum.'],['Ich freue mich auf eine Einladung zum Gespräch.','Espero una invitación a una entrevista.'],['Mit freundlichen Grüßen, Ana Ruiz','Atentamente, Ana Ruiz']],
questions:[['¿Qué solicita?','Un puesto de asistente','Un curso','Una factura'],['¿Qué adjunta?','Su currículum','Una foto','Un contrato']],
drills:[['Escribe el saludo formal a un hombre, Herr Klein:','Sehr geehrter Herr Klein,','Sehr geehrter Herr Klein'],['Escribe la despedida formal:','Mit freundlichen Grüßen'],['Hazlo formal: Schick mir das.','Könnten Sie mir das bitte schicken?']],
write:{prompt:'Escribe un correo formal pidiendo información sobre un curso.',model:'Sehr geehrte Damen und Herren, ich interessiere mich für Ihren Deutschkurs. Könnten Sie mir bitte die Preise schicken? Ich freue mich auf Ihre Antwort. Mit freundlichen Grüßen, Ana Ruiz'}},
{id:'de-12',level:'B1+',title:'Reclamar',goal:'presentar una queja firme y cortés.',
rule:'Una queja: qué compraste, qué pasó, qué pides. Ich möchte mich beschweren. Leider funktioniert das Gerät nicht. Ich bitte Sie um eine Rückerstattung (reembolso) o um Ersatz (reemplazo). Sich beschweren über + acusativo. Bitten um + acusativo. Evita acusar: Das Gerät kam beschädigt an, mejor que Sie haben es beschädigt.',
items:[['Ich möchte mich beschweren.','Quiero presentar una queja.'],['Leider funktioniert das Gerät nicht.','Por desgracia el aparato no funciona.'],['Ich bitte um eine Rückerstattung.','Solicito un reembolso.'],['Das Paket kam beschädigt an.','El paquete llegó dañado.'],['die Rechnung','la factura'],['die Garantie','la garantía'],['umtauschen','cambiar un producto'],['enttäuscht','decepcionado']],
textTitle:'Eine Beschwerde',text:[['Am 3. März habe ich bei Ihnen einen Laptop bestellt.','El 3 de marzo les pedí un portátil.'],['Das Paket kam leider beschädigt an.','Por desgracia el paquete llegó dañado.'],['Ich habe zweimal angerufen, aber niemand konnte mir helfen.','He llamado dos veces, pero nadie pudo ayudarme.'],['Ich bin von Ihrem Service sehr enttäuscht.','Estoy muy decepcionado con su servicio.'],['Ich bitte um eine Rückerstattung innerhalb von sieben Tagen.','Solicito un reembolso en siete días.']],
questions:[['¿Qué le pasó al paquete?','Llegó dañado','No llegó','Era otro'],['¿Qué solicita?','Reembolso','Otro portátil','Una disculpa']],
drills:[['Escribe en alemán: «Quiero cambiar este producto.»','Ich möchte dieses Produkt umtauschen.'],['Completa: Ich beschwere mich ___ den Service.','über'],['Completa: Ich bitte ___ eine Antwort.','um']],
write:{prompt:'Escribe una queja a un hotel.',model:'Sehr geehrte Damen und Herren, ich war letzte Woche in Ihrem Hotel. Leider war das Zimmer schmutzig. Ich bin enttäuscht und bitte um eine Rückerstattung. Mit freundlichen Grüßen'}},
{id:'de-13',level:'B1+',title:'Opinar con argumentos',goal:'defender una opinión de forma ordenada.',
rule:'Orden: Meiner Meinung nach (+ verbo: Meiner Meinung nach ist das falsch), Ich bin der Ansicht, dass; razón: Der wichtigste Grund ist, dass; ejemplo: Zum Beispiel; objeción: Manche meinen, dass; conclusión: Insgesamt. Einerseits … andererseits presenta los dos lados. Ich stimme zu = estoy de acuerdo; ich bin dagegen = estoy en contra.',
items:[['Meiner Meinung nach ist das falsch.','En mi opinión, eso es incorrecto.'],['Ich bin der Ansicht, dass wir handeln müssen.','Opino que debemos actuar.'],['Der wichtigste Grund ist die Umwelt.','La razón principal es el medio ambiente.'],['Einerseits ist es teuer, andererseits nützlich.','Por un lado es caro; por otro, útil.'],['Ich stimme dir zu.','Estoy de acuerdo contigo.'],['Insgesamt bin ich dagegen.','En conjunto, estoy en contra.'],['der Vorteil','la ventaja'],['der Nachteil','la desventaja']],
textTitle:'Autos in der Innenstadt?',text:[['Meiner Meinung nach sollten Autos aus der Innenstadt verschwinden.','En mi opinión, los coches deberían desaparecer del centro.'],['Der wichtigste Grund ist die Luftverschmutzung.','La razón principal es la contaminación.'],['Einerseits verlieren Geschäfte vielleicht Kunden.','Por un lado, las tiendas quizá pierdan clientes.'],['Andererseits ziehen ruhige Straßen mehr Besucher an.','Por otro, las calles tranquilas atraen a más visitantes.'],['Insgesamt überwiegen die Vorteile.','En conjunto predominan las ventajas.']],
questions:[['¿Qué defiende?','Sacar los coches del centro','Más aparcamiento','Cerrar tiendas'],['¿Qué atraen las calles tranquilas?','Más visitantes','Más coches','Más ruido']],
drills:[['Corrige: Meiner Meinung nach das ist gut.','Meiner Meinung nach ist das gut.'],['Escribe en alemán: «Estoy en contra.»','Ich bin dagegen.'],['Completa: Einerseits ist es gut, ___ ist es teuer.','andererseits']],
write:{prompt:'¿Deberíamos trabajar cuatro días a la semana? Argumenta.',model:'Meiner Meinung nach wäre die Vier-Tage-Woche gut. Der wichtigste Grund ist die Gesundheit. Einerseits kostet sie Geld, andererseits sind Menschen dann produktiver. Insgesamt bin ich dafür.'}},
{id:'de-14',level:'B1+',title:'Describir datos',goal:'presentar cifras y resumir un texto.',
rule:'Cifras: steigen (subir), sinken (bajar), gleich bleiben (mantenerse). Um indica la diferencia: um 5 Prozent; auf indica el resultado: auf 20 Prozent. Partes: die Hälfte, ein Drittel, die Mehrheit. Resumir: Der Text handelt von, Der Autor meint, dass, Zusammenfassend lässt sich sagen. Se resume en presente y con palabras propias.',
items:[['Die Preise sind um fünf Prozent gestiegen.','Los precios subieron un cinco por ciento.'],['Die Zahl sank auf zwanzig Prozent.','La cifra bajó al veinte por ciento.'],['Die Hälfte der Befragten stimmt zu.','La mitad de los encuestados está de acuerdo.'],['Der Text handelt von der Arbeit.','El texto trata del trabajo.'],['Zusammenfassend lässt sich sagen, dass es hilft.','En resumen, se puede decir que ayuda.'],['die Grafik','el gráfico'],['ungefähr','aproximadamente'],['im Vergleich zu','en comparación con']],
textTitle:'Der Jahresbericht',text:[['Der Bericht zeigt, dass der Onlinehandel um zwölf Prozent gestiegen ist.','El informe muestra que el comercio online subió un doce por ciento.'],['In den Geschäften blieben die Zahlen gleich.','En las tiendas las cifras se mantuvieron.'],['Ungefähr ein Drittel kauft mit dem Handy.','Aproximadamente un tercio compra con el móvil.'],['Für die Mehrheit ist die Lieferzeit am wichtigsten.','Para la mayoría, el plazo de entrega es lo más importante.'],['Zusammenfassend lässt sich sagen, dass Schnelligkeit entscheidet.','En resumen, la rapidez es lo decisivo.']],
questions:[['¿Cuánto subió el comercio online?','Un doce por ciento','Un tercio','La mitad'],['¿Qué decide el mercado?','La rapidez','El precio','La marca']],
drills:[['Elige um o auf: Der Preis stieg ___ 10 Prozent (diferencia).','um'],['Escribe en alemán: «El texto trata de la salud.»','Der Text handelt von der Gesundheit.'],['Escribe en alemán: «la mitad»','die Hälfte']],
write:{prompt:'Resume el texto de hoy en tres frases.',model:'Der Text handelt vom Onlinehandel. Die Verkäufe sind stark gestiegen, in den Geschäften nicht. Zusammenfassend lässt sich sagen, dass die Lieferzeit am wichtigsten ist.'}},
{id:'de-15',level:'B1+',title:'Reuniones y acuerdos',goal:'intervenir en una reunión y negociar.',
rule:'Intervenir: Darf ich kurz etwas sagen? Aclarar: Ich meine damit, dass… Proponer: Wie wäre es, wenn wir…? Wir könnten… Negociar: Einverstanden, unter der Bedingung, dass… Ceder: Damit kann ich leben. Cerrar: Fassen wir zusammen. Unter der Bedingung lleva dass y verbo al final. Wie wäre es usa Konjunktiv II.',
items:[['Darf ich kurz etwas sagen?','¿Puedo decir algo un momento?'],['Wie wäre es, wenn wir teilen?','¿Y si lo dividimos?'],['Einverstanden, unter der Bedingung, dass es schriftlich ist.','De acuerdo, con la condición de que sea por escrito.'],['Damit kann ich leben.','Puedo aceptarlo.'],['Fassen wir zusammen.','Resumamos.'],['der Kompromiss','el compromiso'],['das Angebot','la oferta'],['der Vorschlag','la propuesta']],
textTitle:'Eine Verhandlung',text:[['Unser Angebot liegt bei zehntausend Euro.','Nuestra oferta es de diez mil euros.'],['Das ist weniger, als wir erwartet haben.','Es menos de lo que esperábamos.'],['Wie wäre es mit einem Kompromiss bei zwölftausend?','¿Qué tal un compromiso de doce mil?'],['Einverstanden, unter der Bedingung, dass Sie in dreißig Tagen zahlen.','De acuerdo, con la condición de que paguen en treinta días.'],['Damit kann ich leben.','Puedo aceptarlo.']],
questions:[['¿Cuál es el precio final?','Doce mil','Diez mil','Treinta mil'],['¿Cuál es la condición?','Pagar en treinta días','Empezar en mayo','Más personal']],
drills:[['Escribe en alemán: «Puedo aceptarlo.»','Damit kann ich leben.'],['Completa: Wie ___ es, wenn wir morgen anfangen?','wäre'],['Escribe en alemán: «Resumamos.»','Fassen wir zusammen.']],
write:{prompt:'Escribe un diálogo negociando vacaciones con tu jefa.',model:'A: Ich möchte im Juli zwei Wochen Urlaub. B: Das ist schwierig. A: Wie wäre es mit einer Woche im Juli und einer im August? B: Damit kann ich leben.'}},
{id:'de-16',level:'B1+',title:'Contar con estilo',goal:'contar una anécdota que mantenga el interés.',
rule:'Por escrito se narra en Präteritum; hablando, en Perfekt con war y hatte. Mantén el interés: Stell dir vor (imagínate), Plötzlich (de repente), Auf einmal, Zum Glück (por suerte), Leider, Am Ende. Si empiezas por una de esas palabras, el verbo va justo detrás: Plötzlich ging das Licht aus. Reacciones: Echt? Das gibt es doch nicht!',
items:[['Stell dir vor, was passiert ist!','¡Imagínate lo que pasó!'],['Plötzlich ging das Licht aus.','De repente se apagó la luz.'],['Zum Glück kam ein Techniker.','Por suerte vino un técnico.'],['Das gibt es doch nicht!','¡No puede ser!'],['der Aufzug','el ascensor'],['stecken bleiben','quedarse atascado'],['erschöpft','agotado'],['aus Versehen','sin querer']],
textTitle:'Im Aufzug',text:[['Stell dir vor, was mir am Freitag passiert ist!','¡Imagínate lo que me pasó el viernes!'],['Ich wollte gerade nach Hause, da blieb der Aufzug stecken.','Justo iba a casa cuando el ascensor se atascó.'],['Plötzlich ging auch noch das Licht aus.','De repente, además, se apagó la luz.'],['Mein Handy hatte natürlich keinen Empfang.','Mi móvil, claro, no tenía cobertura.'],['Nach zwei Stunden kam zum Glück ein Techniker.','Tras dos horas, por suerte, llegó un técnico.']],
questions:[['¿Dónde se quedó?','En el ascensor','En el metro','En el coche'],['¿Cuánto tardó el técnico?','Dos horas','Diez minutos','Todo el día']],
drills:[['Corrige: Plötzlich das Licht ging aus.','Plötzlich ging das Licht aus.'],['Escribe en alemán: «Por suerte, tenía dinero.»','Zum Glück hatte ich Geld.'],['Escribe en alemán: «sin querer»','aus Versehen']],
write:{prompt:'Cuenta la historia más rara que te haya pasado.',model:'Stell dir vor, wen ich am Flughafen getroffen habe! Ich wartete gerade, da sah ich meine alte Lehrerin. Zum Glück erkannte sie mich sofort.'}},
{id:'de-17',level:'B1+',title:'Medio ambiente',goal:'hablar de problemas sociales con precisión.',
rule:'Causa: führt zu (lleva a), liegt an (se debe a), wird verursacht durch (es causado por). Solución: Man sollte, Eine Lösung wäre, Es ist notwendig, dass. Führen zu y liegen an llevan dativo: führt zu höheren Temperaturen. Durch + acusativo indica medio o causa: durch den Verkehr.',
items:[['Das führt zu höheren Temperaturen.','Esto lleva a temperaturas más altas.'],['Das liegt am Verkehr.','Se debe al tráfico.'],['Eine Lösung wäre, weniger zu fliegen.','Una solución sería volar menos.'],['Es ist notwendig, dass wir handeln.','Es necesario que actuemos.'],['der Klimawandel','el cambio climático'],['die erneuerbare Energie','la energía renovable'],['der Müll','la basura'],['der Umweltschutz','la protección del medio ambiente']],
textTitle:'Eine grüne Stadt',text:[['Die Luftverschmutzung in Städten liegt vor allem am Verkehr.','La contaminación en las ciudades se debe sobre todo al tráfico.'],['Das führt zu ernsten Problemen, besonders bei Kindern.','Esto lleva a problemas serios, sobre todo en los niños.'],['Eine Lösung wäre, mehr in Busse und Bahnen zu investieren.','Una solución sería invertir más en autobuses y trenes.'],['Mehrere Städte nutzen schon erneuerbare Energie.','Varias ciudades ya usan energía renovable.'],['Es ist notwendig, dass Politik und Bürger zusammenarbeiten.','Es necesario que política y ciudadanos colaboren.']],
questions:[['¿A qué se debe la contaminación?','Al tráfico','A las fábricas','Al clima'],['¿A quién afecta más?','A los niños','A los conductores','A los ancianos']],
drills:[['Completa: Das führt ___ Problemen.','zu'],['Completa: Das liegt ___ Wetter.','am'],['Escribe en alemán: «Una solución sería reciclar más.»','Eine Lösung wäre, mehr zu recyceln.']],
write:{prompt:'Explica un problema de tu ciudad: causa, efecto y solución.',model:'In meiner Stadt gibt es viel Verkehr. Das liegt am schlechten Nahverkehr und führt zu Stress. Eine Lösung wäre, eine neue U-Bahn zu bauen.'}},
{id:'de-18',level:'B1+',title:'Tecnología y trabajo',goal:'debatir sobre tecnología.',
rule:'Conceder y volver a tu idea: Zwar spart das Zeit, aber es kostet Jobs. Zwar va con aber o doch. Während y wohingegen contrastan con verbo al final. Es bleibt abzuwarten, ob… = está por ver si… Nicht nur … sondern auch añade. Trotzdem significa aun así y cuenta como posición 1, así que el verbo va detrás.',
items:[['Zwar spart das Zeit, aber es kostet Jobs.','Es cierto que ahorra tiempo, pero cuesta empleos.'],['Es bleibt abzuwarten, ob es klappt.','Está por ver si funciona.'],['Trotzdem bin ich optimistisch.','Aun así, soy optimista.'],['die Künstliche Intelligenz','la inteligencia artificial'],['die Fähigkeit','la habilidad'],['ersetzen','reemplazar'],['die Weiterbildung','la formación continua'],['der Arbeitsplatz','el puesto de trabajo']],
textTitle:'Maschinen und Menschen',text:[['Zwar machen Maschinen Firmen produktiver, aber sie gefährden Arbeitsplätze.','Es cierto que las máquinas hacen más productivas a las empresas, pero amenazan empleos.'],['Sie ersetzen oft einzelne Aufgaben, selten ganze Berufe.','Suelen reemplazar tareas sueltas, rara vez profesiones enteras.'],['Nicht nur neue Fähigkeiten sind nötig, sondern auch Zeit zum Lernen.','No solo hacen falta nuevas habilidades, sino también tiempo para aprender.'],['Deshalb wird Weiterbildung immer wichtiger.','Por eso la formación continua es cada vez más importante.'],['Es bleibt abzuwarten, ob die Politik hilft.','Está por ver si la política ayuda.']],
questions:[['¿Qué reemplazan las máquinas?','Tareas sueltas','Fábricas enteras','Todo'],['¿Qué es cada vez más importante?','La formación continua','El salario','La política']],
drills:[['Completa: Zwar ist es teuer, ___ es lohnt sich.','aber','doch'],['Corrige: Trotzdem ich bin optimistisch.','Trotzdem bin ich optimistisch.'],['Escribe en alemán: «Está por ver.»','Es bleibt abzuwarten.']],
write:{prompt:'Escribe un párrafo equilibrado: ¿la tecnología nos da más tiempo?',model:'Zwar spart Technik im Beruf Zeit, aber wir sind immer erreichbar. Trotzdem möchte ich nicht ohne Handy leben. Es bleibt abzuwarten, ob sich das ändert.'}},
{id:'de-19',level:'B1+',title:'Vida en Alemania',goal:'entender temas de la vida diaria y sus trámites.',
rule:'Para hablar de reglas y costumbres: man + verbo (Man trennt den Müll), es ist üblich, dass, es ist verboten. Dürfen negado = prohibido: Man darf hier nicht rauchen. Müssen negado = no hace falta: Du musst nicht kommen. Esta diferencia es la que más confunde a un hispanohablante.',
items:[['Man trennt den Müll.','Se separa la basura.'],['Es ist üblich, pünktlich zu sein.','Lo normal es ser puntual.'],['Hier darf man nicht rauchen.','Aquí no se puede fumar.'],['Du musst nicht kommen.','No tienes que venir.'],['sich anmelden','registrarse'],['die Miete','el alquiler'],['die Krankenversicherung','el seguro médico'],['die Steuern','los impuestos']],
textTitle:'Neu in Deutschland',text:[['Wer nach Deutschland zieht, muss sich beim Amt anmelden.','Quien se muda a Alemania debe registrarse en la oficina.'],['Eine Krankenversicherung ist für alle Pflicht.','El seguro médico es obligatorio para todos.'],['Es ist üblich, den Müll sorgfältig zu trennen.','Lo normal es separar la basura con cuidado.'],['Sonntags sind fast alle Geschäfte geschlossen.','Los domingos casi todas las tiendas están cerradas.'],['Pünktlichkeit ist hier wichtiger als in vielen anderen Ländern.','La puntualidad es aquí más importante que en muchos otros países.']],
questions:[['¿Qué es obligatorio?','El seguro médico','Comprar los domingos','Hablar alemán'],['¿Qué pasa los domingos?','Las tiendas cierran','Hay mercado','Se trabaja más']],
drills:[['Elige: «No tienes que pagar.» Du ___ nicht zahlen.','musst'],['Elige: «Está prohibido fumar.» Man ___ nicht rauchen.','darf'],['Escribe en alemán: «Se separa la basura.»','Man trennt den Müll.']],
write:{prompt:'Explica tres reglas o costumbres de tu país a un alemán.',model:'In Mexiko isst man spät zu Mittag. Es ist üblich, Fremde zu begrüßen. Man muss nicht immer pünktlich sein.'}},
{id:'de-20',level:'B1+',title:'Prueba de escritura: ensayo',goal:'escribir un texto largo con estructura.',
rule:'Un texto argumentativo tiene cuatro partes. Einleitung: presenta el tema. Hauptteil: argumentos a favor y en contra. Schluss: tu conclusión. Conectores: Zunächst, Außerdem, Dagegen, Abschließend. Revisa al final: verbo en segunda posición, verbo al final tras weil y dass, mayúsculas de nombres y casos tras preposición.',
items:[['Zunächst möchte ich sagen, dass…','En primer lugar quisiera decir que…'],['Außerdem spielt das Geld eine Rolle.','Además, el dinero juega un papel.'],['Dagegen spricht, dass es teuer ist.','En contra está que es caro.'],['Abschließend bin ich dafür.','Para concluir, estoy a favor.'],['die Einleitung','la introducción'],['der Hauptteil','el cuerpo'],['der Schluss','la conclusión'],['überzeugen','convencer']],
textTitle:'Fremdsprachen lernen',text:[['Viele Erwachsene glauben, es sei zu spät, eine Sprache zu lernen.','Muchos adultos creen que es tarde para aprender un idioma.'],['Zunächst zeigt die Forschung, dass Erwachsene sehr gut lernen.','Primero, la investigación muestra que los adultos aprenden muy bien.'],['Außerdem öffnet eine neue Sprache viele Türen.','Además, un nuevo idioma abre muchas puertas.'],['Dagegen spricht, dass es viel Zeit kostet.','En contra está que cuesta mucho tiempo.'],['Abschließend überzeugen mich die Vorteile.','Para concluir, me convencen las ventajas.']],
questions:[['¿Qué muestra la investigación?','Los adultos aprenden bien','Es tarde','Solo los niños aprenden'],['¿Qué argumento hay en contra?','Cuesta mucho tiempo','Es caro','Es inútil']],
drills:[['Escribe en alemán: «Además»','Außerdem'],['Corrige: Ich glaube, dass es ist richtig.','Ich glaube, dass es richtig ist.'],['Corrige: Weil ich bin müde, schlafe ich.','Weil ich müde bin, schlafe ich.']],
write:{prompt:'Escribe 100 a 150 palabras: ¿debería ser gratis el transporte público?',model:'Viele Menschen fordern kostenlosen Nahverkehr. Zunächst wäre das gut für die Umwelt, weil weniger Autos fahren würden. Außerdem würden Familien Geld sparen. Dagegen spricht, dass die Städte das bezahlen müssten. Abschließend bin ich trotzdem dafür, weil die Vorteile größer sind.'}},
];

// Alemán B2: precisión y textos de opinión.
export const GERMAN_B2=[
{id:'de-b2-01',level:'B2',title:'Dar a entender lo que otros dicen',goal:'citar con distancia en textos formales.',
rule:'Además del Konjunktiv I, hay verbos que marcan distancia: sollen (Er soll reich sein: dicen que es rico) y wollen (Er will es gesehen haben: afirma haberlo visto, pero lo dudo). Otras fórmulas: angeblich (supuestamente), laut + dativo, Berichten zufolge. En la prensa son constantes y cambian el sentido de la frase.',
items:[['Er soll sehr reich sein.','Dicen que es muy rico.'],['Sie will nichts gewusst haben.','Afirma no haber sabido nada.'],['Angeblich wurde das Geld gestohlen.','Supuestamente se robó el dinero.'],['Berichten zufolge gibt es Verletzte.','Según las informaciones, hay heridos.'],['die Behauptung','la afirmación'],['die Quelle','la fuente'],['bestätigen','confirmar']],
textTitle:'Ein Skandal',text:[['Der Bürgermeister soll Gelder der Stadt für private Reisen genutzt haben.','Al parecer el alcalde usó fondos municipales para viajes privados.'],['Er selbst will von den Zahlungen nichts gewusst haben.','Él afirma no haber sabido nada de los pagos.'],['Angeblich hat ein Mitarbeiter die Belege gefälscht.','Supuestamente un empleado falsificó los recibos.'],['Berichten zufolge ermittelt bereits die Staatsanwaltschaft.','Según las informaciones, la fiscalía ya investiga.'],['Eine offizielle Bestätigung gibt es bisher nicht.','Hasta ahora no hay confirmación oficial.']],
questions:[['¿Qué dice el alcalde?','Que no sabía nada','Que fue él','Que es mentira de la prensa'],['¿Hay confirmación oficial?','No','Sí','A medias']],
drills:[['Reescribe con sollen: Man sagt, sie ist krank.','Sie soll krank sein.'],['Reescribe con wollen: Er behauptet, dass er es gesehen hat.','Er will es gesehen haben.'],['Escribe en alemán: «supuestamente»','angeblich']],
write:{prompt:'Resume una noticia polémica marcando lo que no está confirmado.',model:'Ein Minister soll Geld angenommen haben. Er selbst will davon nichts gewusst haben. Berichten zufolge gibt es aber Beweise.'}},
{id:'de-b2-02',level:'B2',title:'Sustantivar como en un informe',goal:'convertir verbos en sustantivos en estilo formal.',
rule:'El alemán escrito formal prefiere sustantivos a verbos: Nachdem wir das Projekt beendet hatten → Nach Beendigung des Projekts. Weil es regnete → Wegen des Regens. Wenn man Fragen hat → Bei Fragen. Se usan nach, vor, bei, wegen, trotz, während con sustantivo. Es más corto, pero también más difícil de leer: reconócelo aunque al hablar no lo uses.',
items:[['Nach Abschluss des Projekts','Tras concluir el proyecto'],['Bei Fragen wenden Sie sich an uns.','Si tiene preguntas, diríjase a nosotros.'],['Wegen des starken Regens','Debido a la fuerte lluvia'],['Vor Beginn der Sitzung','Antes del comienzo de la sesión'],['Trotz großer Bemühungen','A pesar de grandes esfuerzos'],['die Durchführung','la realización'],['die Einführung','la introducción']],
textTitle:'Eine Mitteilung der Firma',text:[['Nach Abschluss der Umbauarbeiten öffnet das Büro wieder am Montag.','Tras concluir las obras, la oficina reabre el lunes.'],['Während der Einführung des neuen Systems kann es zu Verzögerungen kommen.','Durante la introducción del nuevo sistema puede haber retrasos.'],['Trotz sorgfältiger Planung sind Probleme nicht auszuschließen.','A pesar de una planificación cuidadosa, no se descartan problemas.'],['Bei technischen Fragen wenden Sie sich bitte an die IT-Abteilung.','Para preguntas técnicas, diríjase al departamento de informática.'],['Vor Beginn der Schulung erhalten alle Mitarbeiter eine Anleitung.','Antes del inicio de la formación, todos reciben unas instrucciones.']],
questions:[['¿Cuándo reabre la oficina?','El lunes','Mañana','En un mes'],['¿A quién se dirigen las preguntas técnicas?','A informática','Al jefe','A recepción']],
drills:[['Sustantiva: Nachdem er angekommen war → Nach ___','Nach seiner Ankunft'],['Sustantiva: Weil es Streik gab → Wegen ___','Wegen des Streiks'],['Sustantiva: Wenn es regnet → Bei ___','Bei Regen']],
write:{prompt:'Escribe un aviso formal de tres frases usando nach, bei y trotz.',model:'Nach Abschluss der Renovierung ist die Bibliothek wieder geöffnet. Bei Fragen hilft Ihnen das Personal. Trotz der Arbeiten bleibt der Eingang zugänglich.'}},
{id:'de-b2-03',level:'B2',title:'Conectores de nivel alto',goal:'argumentar con conectores formales.',
rule:'Para textos de B2: zumal (sobre todo porque), indem (mediante, al hacer), sodass (de modo que), anstatt dass, falls, sofern (siempre que), es sei denn (a menos que). Todos mandan el verbo al final, salvo es sei denn, que va seguido de una frase normal. Indem explica el modo: Man spart Geld, indem man weniger fährt.',
items:[['Man spart Energie, indem man weniger heizt.','Se ahorra energía calentando menos.'],['Ich komme nicht, zumal ich krank bin.','No voy, sobre todo porque estoy enfermo.'],['Sofern es nicht regnet, gehen wir.','Siempre que no llueva, vamos.'],['Wir fahren, es sei denn, es schneit.','Vamos, a menos que nieve.'],['Es war laut, sodass ich nicht schlafen konnte.','Había ruido, de modo que no pude dormir.'],['vorausgesetzt','suponiendo que'],['ohnehin','de todos modos']],
textTitle:'Weniger Fleisch?',text:[['Viele Menschen essen weniger Fleisch, zumal die Preise gestiegen sind.','Mucha gente come menos carne, sobre todo porque los precios han subido.'],['Man kann das Klima schützen, indem man regionale Produkte kauft.','Se puede proteger el clima comprando productos regionales.'],['Sofern die Qualität stimmt, zahlen viele auch mehr.','Siempre que la calidad sea buena, muchos pagan más.'],['Vegetarische Gerichte werden beliebter, sodass Restaurants ihre Karten ändern.','Los platos vegetarianos son más populares, de modo que los restaurantes cambian su carta.'],['Ein völliger Verzicht ist nicht nötig, es sei denn, man möchte es.','Una renuncia total no es necesaria, a menos que uno quiera.']],
questions:[['¿Por qué comen menos carne?','Han subido los precios','Por salud solamente','Por ley'],['¿Qué hacen los restaurantes?','Cambian su carta','Cierran','Suben precios']],
drills:[['Une con indem: Er lernt. Er liest viel.','Er lernt, indem er viel liest.'],['Une con sodass: Es regnete. Wir blieben zu Hause.','Es regnete, sodass wir zu Hause blieben.'],['Escribe en alemán: «a menos que»','es sei denn']],
write:{prompt:'Explica cómo ahorrar dinero en tu vida diaria con indem, sofern y zumal.',model:'Man spart Geld, indem man selbst kocht. Sofern man Zeit hat, ist das auch gesünder. Ich koche gern, zumal es mir Spaß macht.'}},
{id:'de-b2-04',level:'B2',title:'Expresiones idiomáticas',goal:'entender modismos frecuentes.',
rule:'Los modismos no se traducen palabra por palabra. Ich verstehe nur Bahnhof: no entiendo nada. Das ist nicht mein Bier: no es asunto mío. Den Nagel auf den Kopf treffen: dar en el clavo. Tomaten auf den Augen haben: no ver lo evidente. Daumen drücken: desear suerte. Úsalos con amigos; en un texto formal, mejor con moderación.',
items:[['Ich verstehe nur Bahnhof.','No entiendo nada.'],['Das ist nicht mein Bier.','No es asunto mío.'],['Du hast den Nagel auf den Kopf getroffen.','Diste en el clavo.'],['Ich drücke dir die Daumen.','Te deseo suerte.'],['Hast du Tomaten auf den Augen?','¿Es que no lo ves?'],['Das ist mir Wurst.','Me da igual.'],['ins Fettnäpfchen treten','meter la pata']],
textTitle:'Ein peinlicher Abend',text:[['Beim Abendessen mit den Eltern meiner Freundin bin ich ins Fettnäpfchen getreten.','En la cena con los padres de mi novia metí la pata.'],['Ich habe gefragt, wie alt ihre Mutter ist, und alle schwiegen.','Pregunté cuántos años tiene su madre y todos se callaron.'],['Als sie über Politik diskutierten, verstand ich nur Bahnhof.','Cuando discutieron de política, no entendí nada.'],['Mein Freund sagte später: „Mach dir nichts draus, das passiert jedem.“','Mi amigo dijo luego: «No te preocupes, le pasa a todo el mundo».'],['Für das nächste Treffen drücken alle mir die Daumen.','Para el próximo encuentro todos me desean suerte.']],
questions:[['¿Qué error cometió?','Preguntó la edad de la madre','Llegó tarde','Rompió algo'],['¿Qué le pasó con la política?','No entendió nada','Discutió','Ganó el debate']],
drills:[['Traduce: «Me da igual.» (modismo con Wurst)','Das ist mir Wurst.','Das ist mir wurst.'],['Traduce: «Te deseo suerte.»','Ich drücke dir die Daumen.'],['¿Qué significa «ins Fettnäpfchen treten»?','meter la pata']],
write:{prompt:'Cuenta una situación embarazosa usando dos modismos.',model:'Im Büro bin ich ins Fettnäpfchen getreten, als ich den Chef mit einem Kunden verwechselt habe. Bei der Besprechung danach verstand ich nur Bahnhof.'}},
{id:'de-b2-05',level:'B2',title:'Futur II y suposiciones',goal:'expresar suposiciones sobre el pasado y el futuro.',
rule:'El Futur II es werden + participio + haben o sein. Sirve para algo terminado en el futuro (Bis Montag werde ich es geschafft haben) y, sobre todo, para suponer sobre el pasado: Er wird den Zug verpasst haben, habrá perdido el tren. Werden + infinitivo con wohl supone sobre el presente: Sie wird wohl krank sein.',
items:[['Er wird den Zug verpasst haben.','Habrá perdido el tren.'],['Sie wird wohl krank sein.','Estará enferma.'],['Bis Freitag werde ich es geschafft haben.','Para el viernes lo habré logrado.'],['Das wird schon stimmen.','Ya será verdad.'],['vermutlich','presumiblemente'],['vermuten','suponer'],['die Vermutung','la suposición']],
textTitle:'Wo ist Paul?',text:[['Paul ist nicht zur Besprechung gekommen.','Paul no vino a la reunión.'],['Er wird wohl wieder im Stau stehen.','Estará otra vez en un atasco.'],['Oder er wird den Termin vergessen haben.','O habrá olvidado la cita.'],['Seine Kollegin meint, er wird krank geworden sein.','Su colega cree que se habrá puesto enfermo.'],['Bis zum Nachmittag wird er sich bestimmt gemeldet haben.','Para la tarde seguro que habrá dado señales de vida.']],
questions:[['¿Qué cree su colega?','Que se habrá puesto enfermo','Que se fue de viaje','Que renunció'],['¿Qué esperan para la tarde?','Que dé señales de vida','Que venga a la oficina','Nada']],
drills:[['Supón: Sie hat es vergessen (Futur II).','Sie wird es vergessen haben.'],['Supón en presente con wohl: Er ist müde.','Er wird wohl müde sein.'],['Escribe en alemán: «Para junio habré terminado.»','Bis Juni werde ich fertig sein.','Bis Juni werde ich es geschafft haben.','Bis Juni werde ich fertig geworden sein.']],
write:{prompt:'Un amigo no responde a tus mensajes. Escribe tres suposiciones.',model:'Er wird sein Handy verloren haben. Vielleicht wird er wohl arbeiten. Oder er wird einfach eingeschlafen sein.'}},
{id:'de-b2-06',level:'B2',title:'Presentar en público',goal:'estructurar una presentación oral.',
rule:'Fórmulas: Ich möchte heute über … sprechen. Zunächst…, anschließend…, zum Schluss… Para ejemplos: Ein gutes Beispiel dafür ist… Para gráficos: Wie Sie auf der Grafik sehen. Para cerrar: Ich komme jetzt zum Schluss. Vielen Dank für Ihre Aufmerksamkeit. Habla de Sie con el público y usa frases cortas.',
items:[['Ich möchte heute über Energie sprechen.','Hoy quiero hablar de energía.'],['Zunächst gebe ich einen Überblick.','Primero doy un panorama general.'],['Wie Sie auf der Grafik sehen…','Como ven en el gráfico…'],['Ich komme jetzt zum Schluss.','Paso ahora a la conclusión.'],['Vielen Dank für Ihre Aufmerksamkeit.','Muchas gracias por su atención.'],['Haben Sie noch Fragen?','¿Tienen alguna pregunta?'],['der Überblick','el panorama general']],
textTitle:'Eine kurze Präsentation',text:[['Ich möchte heute über das Thema Homeoffice sprechen.','Hoy quiero hablar del teletrabajo.'],['Zunächst zeige ich, wie sich die Zahlen entwickelt haben.','Primero muestro cómo han evolucionado las cifras.'],['Wie Sie auf der Grafik sehen, arbeitet jeder Dritte teilweise zu Hause.','Como ven en el gráfico, uno de cada tres trabaja parcialmente en casa.'],['Anschließend spreche ich über Vor- und Nachteile.','A continuación hablo de ventajas y desventajas.'],['Ich komme jetzt zum Schluss: Eine Mischung scheint ideal zu sein.','Paso a la conclusión: una mezcla parece ideal.']],
questions:[['¿Cuántos trabajan en parte desde casa?','Uno de cada tres','La mitad','Casi nadie'],['¿Qué conclusión da?','Una mezcla es ideal','Todos deben volver','Todos en casa']],
drills:[['Escribe en alemán: «Primero doy un panorama.»','Zunächst gebe ich einen Überblick.'],['Escribe en alemán: «Paso a la conclusión.»','Ich komme jetzt zum Schluss.','Ich komme zum Schluss.'],['Escribe en alemán: «¿Tienen preguntas?»','Haben Sie Fragen?','Haben Sie noch Fragen?']],
write:{prompt:'Prepara el guion de una presentación de un minuto sobre tu ciudad.',model:'Ich möchte heute über meine Stadt sprechen. Zunächst erzähle ich etwas über ihre Geschichte. Anschließend zeige ich die schönsten Orte. Vielen Dank für Ihre Aufmerksamkeit.'}},
{id:'de-b2-07',level:'B2',title:'Migración e integración',goal:'debatir un tema social complejo.',
rule:'Vocabulario de debate social: die Integration, die Zuwanderung, die Vielfalt, die Chancengleichheit, Vorurteile abbauen, sich anpassen, gesellschaftliche Teilhabe. Para matizar: Es lässt sich nicht leugnen, dass… (no se puede negar que); Es wäre falsch zu behaupten, dass… (sería un error afirmar que). Ambas preparan una opinión equilibrada.',
items:[['Es lässt sich nicht leugnen, dass es Probleme gibt.','No se puede negar que hay problemas.'],['Es wäre falsch zu behaupten, dass alles schlecht ist.','Sería un error afirmar que todo está mal.'],['Vorurteile abbauen','reducir prejuicios'],['die Chancengleichheit','la igualdad de oportunidades'],['die Vielfalt','la diversidad'],['die Zuwanderung','la inmigración'],['die Teilhabe','la participación']],
textTitle:'Integration gelingt im Alltag',text:[['Es lässt sich nicht leugnen, dass Integration Zeit braucht.','No se puede negar que la integración requiere tiempo.'],['Sprachkurse allein reichen oft nicht aus.','Los cursos de idiomas solos a menudo no bastan.'],['Entscheidend sind Kontakte am Arbeitsplatz, in Vereinen und in der Nachbarschaft.','Lo decisivo son los contactos en el trabajo, en asociaciones y en el vecindario.'],['Es wäre falsch zu behaupten, dass Zuwanderung nur Probleme bringt.','Sería un error afirmar que la inmigración solo trae problemas.'],['Viele Branchen wären ohne zugewanderte Fachkräfte kaum funktionsfähig.','Muchos sectores apenas funcionarían sin profesionales inmigrantes.']],
questions:[['¿Qué es decisivo para integrarse?','Los contactos cotidianos','Solo los cursos','Las leyes'],['¿Qué pasaría en muchos sectores sin inmigrantes?','Apenas funcionarían','Mejorarían','Nada']],
drills:[['Escribe en alemán: «No se puede negar que…»','Es lässt sich nicht leugnen, dass','Es lässt sich nicht leugnen, dass…'],['Escribe en alemán: «reducir prejuicios»','Vorurteile abbauen'],['Escribe en alemán: «la diversidad»','die Vielfalt']],
write:{prompt:'¿Qué ayuda más a integrarse en un país nuevo? Escribe un párrafo equilibrado.',model:'Es lässt sich nicht leugnen, dass die Sprache wichtig ist. Es wäre aber falsch zu behaupten, dass sie allein genügt. Entscheidend sind Freundschaften und Arbeit.'}},
{id:'de-b2-08',level:'B2',title:'Lenguaje del trabajo',goal:'manejarte en reuniones y evaluaciones de trabajo.',
rule:'En el trabajo aparecen expresiones fijas: einen Termin vereinbaren, eine Frist einhalten (cumplir un plazo), Verantwortung übernehmen, in Rücksprache mit (consultando con), zur Kenntnis nehmen (tomar nota), etwas in Angriff nehmen (abordar). En una evaluación: Ihre Stärken liegen in…, Verbesserungspotenzial gibt es bei…',
items:[['Wir müssen die Frist einhalten.','Debemos cumplir el plazo.'],['Ich übernehme die Verantwortung.','Asumo la responsabilidad.'],['in Rücksprache mit der Chefin','consultando con la jefa'],['Ich nehme das zur Kenntnis.','Tomo nota de ello.'],['Lass uns das in Angriff nehmen.','Abordémoslo.'],['Ihre Stärken liegen in der Planung.','Sus puntos fuertes están en la planificación.'],['das Verbesserungspotenzial','el margen de mejora']],
textTitle:'Das Mitarbeitergespräch',text:[['Im jährlichen Mitarbeitergespräch lobte die Chefin Annas Arbeit.','En la entrevista anual la jefa elogió el trabajo de Anna.'],['Ihre Stärken lägen vor allem in der Organisation.','Sus fortalezas estarían sobre todo en la organización.'],['Verbesserungspotenzial gebe es bei der Kommunikation mit Kunden.','Habría margen de mejora en la comunicación con clientes.'],['Anna nahm die Kritik zur Kenntnis und schlug eine Schulung vor.','Anna tomó nota de la crítica y propuso una formación.'],['In Rücksprache mit der Personalabteilung wurde der Kurs genehmigt.','Consultando con personal, se aprobó el curso.']],
questions:[['¿En qué es fuerte Anna?','En la organización','En las ventas','En idiomas'],['¿Qué propuso ella?','Una formación','Un aumento','Cambiar de puesto']],
drills:[['Escribe en alemán: «cumplir un plazo»','eine Frist einhalten'],['Escribe en alemán: «Asumo la responsabilidad.»','Ich übernehme die Verantwortung.'],['Escribe en alemán: «Tomo nota.»','Ich nehme das zur Kenntnis.']],
write:{prompt:'Escribe tu propia evaluación: tus fortalezas y dónde puedes mejorar.',model:'Meine Stärken liegen in der Teamarbeit. Verbesserungspotenzial gibt es bei der Zeitplanung. Ich möchte das im nächsten Jahr in Angriff nehmen.'}},
{id:'de-b2-09',level:'B2',title:'Literatura breve',goal:'leer y comentar un texto literario.',
rule:'Para comentar un texto: Der Text handelt von…, Die Hauptfigur ist…, Der Autor beschreibt…, Die Stimmung ist bedrückend/heiter, Es geht um…, Der Text regt zum Nachdenken an. La literatura usa Präteritum y a veces Konjunktiv II para sueños o deseos. Primero entiende la idea general, luego los detalles.',
items:[['Der Text handelt von einer Reise.','El texto trata de un viaje.'],['Die Hauptfigur ist ein alter Mann.','El protagonista es un anciano.'],['Die Stimmung ist bedrückend.','El ambiente es opresivo.'],['Der Text regt zum Nachdenken an.','El texto invita a reflexionar.'],['die Erzählung','el relato'],['der Erzähler','el narrador'],['die Andeutung','la insinuación']],
textTitle:'Der Bahnsteig',text:[['Jeden Abend saß der alte Mann auf derselben Bank am Bahnsteig.','Cada noche el anciano se sentaba en el mismo banco del andén.'],['Er stieg nie in einen Zug, er schaute nur den Reisenden nach.','Nunca subía a un tren; solo miraba a los viajeros.'],['Einmal fragte ihn ein Kind, auf wen er warte.','Una vez un niño le preguntó a quién esperaba.'],['„Auf mich selbst“, sagte er, „auf den, der ich hätte werden können.“','«A mí mismo», dijo, «al que podría haber llegado a ser».'],['Das Kind verstand ihn nicht, doch es setzte sich schweigend neben ihn.','El niño no lo entendió, pero se sentó en silencio a su lado.']],
questions:[['¿Qué hacía el anciano?','Miraba a los viajeros','Viajaba cada noche','Vendía billetes'],['¿A quién esperaba?','A sí mismo, al que pudo ser','A su hijo','A un tren concreto']],
drills:[['Escribe en alemán: «El texto trata de…»','Der Text handelt von','Der Text handelt von…'],['Escribe en alemán: «el narrador»','der Erzähler'],['¿Qué tiempo es «hätte werden können»?','Konjunktiv II','Konjunktiv II Vergangenheit']],
write:{prompt:'Comenta el texto: de qué trata, cómo es el ambiente y qué te hace pensar.',model:'Der Text handelt von einem alten Mann, der jeden Abend am Bahnhof sitzt. Die Stimmung ist melancholisch. Der Text regt zum Nachdenken über verpasste Chancen an.'}},
{id:'de-b2-10',level:'B2',title:'Precisión en preposiciones',goal:'evitar errores de preposición en alemán avanzado.',
rule:'Errores típicos: abhängig von (depender de), stolz auf, zufrieden mit, verantwortlich für, interessiert an, bekannt für, schuld an, gespannt auf (impaciente por). Con verbos: sich bewerben um (un puesto) / bei (una empresa), sich verlassen auf, bestehen aus (consistir en), bestehen auf (insistir en). Apréndelos como bloque.',
items:[['Ich bin stolz auf dich.','Estoy orgulloso de ti.'],['Sie ist zufrieden mit dem Ergebnis.','Está satisfecha con el resultado.'],['Ich bewerbe mich um die Stelle bei Siemens.','Me postulo al puesto en Siemens.'],['Das Team besteht aus fünf Personen.','El equipo consta de cinco personas.'],['Er besteht auf einer Antwort.','Insiste en una respuesta.'],['Ich bin gespannt auf das Ergebnis.','Estoy impaciente por el resultado.'],['Du kannst dich auf mich verlassen.','Puedes contar conmigo.']],
textTitle:'Die Bewerbung',text:[['Lukas bewirbt sich um eine Stelle bei einer Bank.','Lukas se postula a un puesto en un banco.'],['Er ist besonders an der Finanzberatung interessiert.','Le interesa especialmente el asesoramiento financiero.'],['Das Auswahlverfahren besteht aus drei Gesprächen.','El proceso de selección consta de tres entrevistas.'],['Seine Eltern sind sehr stolz auf ihn.','Sus padres están muy orgullosos de él.'],['Er ist gespannt auf die Antwort.','Está impaciente por la respuesta.']],
questions:[['¿Qué le interesa a Lukas?','El asesoramiento financiero','La informática','Las ventas'],['¿De cuántas entrevistas consta?','Tres','Una','Cinco']],
drills:[['Completa: Ich bin stolz ___ meine Familie.','auf'],['Completa: Das Buch besteht ___ zehn Kapiteln.','aus'],['Completa: Er ist verantwortlich ___ das Projekt.','für']],
write:{prompt:'Escribe cinco frases sobre tu trabajo o estudios con estas preposiciones.',model:'Ich bin mit meiner Arbeit zufrieden. Ich bin für zwei Projekte verantwortlich. Ich bin stolz auf mein Team und gespannt auf das neue Jahr.'}},
{id:'de-b2-11',level:'B2',title:'Carta de lectores',goal:'escribir una opinión pública convincente.',
rule:'Una carta de lectores (Leserbrief): referencia al artículo (In Ihrem Artikel vom … schreiben Sie, dass…), tu postura, dos argumentos, una propuesta y un cierre. Para reforzar: Ich bin fest davon überzeugt, dass… Para matizar: Zwar…, doch… Para proponer: Es wäre sinnvoll, wenn… El registro es formal pero personal.',
items:[['In Ihrem Artikel schreiben Sie, dass…','En su artículo escribe usted que…'],['Ich bin fest davon überzeugt, dass…','Estoy firmemente convencido de que…'],['Es wäre sinnvoll, wenn die Stadt handelt.','Sería sensato que la ciudad actuara.'],['Zwar stimmt das, doch…','Es cierto, pero…'],['der Leserbrief','la carta al director'],['überzeugen','convencer'],['die Forderung','la exigencia']],
textTitle:'Ein Leserbrief',text:[['In Ihrem Artikel vom 3. Mai schreiben Sie, dass Radwege zu teuer seien.','En su artículo del 3 de mayo escribe que los carriles bici serían demasiado caros.'],['Ich bin fest davon überzeugt, dass das Gegenteil der Fall ist.','Estoy firmemente convencido de lo contrario.'],['Zwar kosten Radwege Geld, doch sie entlasten die Straßen und die Umwelt.','Es cierto que cuestan dinero, pero alivian las calles y el medio ambiente.'],['Außerdem fördern sie die Gesundheit der Bürger.','Además fomentan la salud de los ciudadanos.'],['Es wäre sinnvoll, wenn die Stadt mutiger investieren würde.','Sería sensato que la ciudad invirtiera con más valentía.']],
questions:[['¿Qué decía el artículo?','Que los carriles bici son caros','Que hay que construir más','Que el tráfico baja'],['¿Qué propone el autor?','Invertir con más valentía','Prohibir bicicletas','Nada']],
drills:[['Escribe en alemán: «Estoy firmemente convencido de que…»','Ich bin fest davon überzeugt, dass','Ich bin fest davon überzeugt, dass…'],['Escribe en alemán: «Sería sensato que…»','Es wäre sinnvoll, wenn','Es wäre sinnvoll, wenn…'],['Escribe en alemán: «la carta al director»','der Leserbrief']],
write:{prompt:'Escribe una carta de lectores de 100 palabras sobre un tema de tu ciudad.',model:'In Ihrem Artikel schreiben Sie, dass der Park geschlossen werden soll. Ich bin fest davon überzeugt, dass das ein Fehler wäre. Zwar kostet die Pflege Geld, doch der Park ist für Familien wichtig. Es wäre sinnvoll, wenn die Stadt eine andere Lösung suchen würde.'}},
{id:'de-b2-12',level:'B2',title:'Debate final',goal:'defender y rebatir posturas en un debate.',
rule:'Rebatir con cortesía: Da muss ich widersprechen. Das sehe ich anders. Ihr Argument überzeugt mich nicht, weil… Conceder: Da haben Sie nicht ganz unrecht. Volver a tu punto: Trotzdem bleibe ich dabei, dass… Para ganar tiempo: Das ist eine gute Frage. En un debate se habla en Konjunktiv II para sonar menos tajante.',
items:[['Da muss ich widersprechen.','Ahí tengo que discrepar.'],['Das sehe ich anders.','Yo lo veo de otro modo.'],['Ihr Argument überzeugt mich nicht.','Su argumento no me convence.'],['Da haben Sie nicht ganz unrecht.','En eso no le falta razón.'],['Trotzdem bleibe ich dabei.','Aun así, mantengo mi postura.'],['Das ist eine gute Frage.','Es una buena pregunta.'],['der Einwand','la objeción']],
textTitle:'Soll Social Media erst ab 16 erlaubt sein?',text:[['A: Ich finde, Kinder sollten erst ab 16 soziale Netzwerke nutzen.','A: Creo que los niños solo deberían usar redes sociales a partir de los 16.'],['B: Da muss ich widersprechen, das wäre kaum kontrollierbar.','B: Ahí tengo que discrepar, apenas sería controlable.'],['A: Da haben Sie nicht ganz unrecht, aber Regeln setzen Signale.','A: No le falta razón, pero las normas envían señales.'],['B: Ihr Argument überzeugt mich nicht, weil Bildung wichtiger ist als Verbote.','B: Su argumento no me convence, porque la educación es más importante que las prohibiciones.'],['A: Trotzdem bleibe ich dabei, dass Kinder geschützt werden müssen.','A: Aun así mantengo que hay que proteger a los niños.']],
questions:[['¿Qué propone A?','Redes solo desde los 16','Prohibirlas del todo','Nada'],['¿Qué prefiere B?','Educación antes que prohibición','Más prohibiciones','Lo mismo que A']],
drills:[['Escribe en alemán: «Yo lo veo de otro modo.»','Das sehe ich anders.'],['Escribe en alemán: «Su argumento no me convence.»','Ihr Argument überzeugt mich nicht.'],['Escribe en alemán: «Aun así mantengo mi postura.»','Trotzdem bleibe ich dabei.']],
write:{prompt:'Escribe un debate breve contigo mismo: una postura, una objeción y tu respuesta.',model:'Ich finde, Fleisch sollte teurer werden. Man könnte einwenden, dass arme Familien darunter leiden. Da ist etwas dran, trotzdem bleibe ich dabei, weil die Umwelt geschützt werden muss.'}},
];
